.panel-list .panel{margin-bottom:14px}.concept b{color:var(--red)}.model{white-space:pre-line}.hero h1{font-size:clamp(32px,4vw,48px)}.source-text{user-select:text}.data-note{font-size:18px}.comic-full{display:block;max-width:100%;height:auto;margin:24px auto}.task-footer{flex-wrap:wrap}@media(max-width:760px){.hero{grid-template-columns:1fr}}
