.answer-table{table-layout:fixed;width:100%}.answer-table thead{display:none}.answer-table tr{display:grid;grid-template-columns:1fr}.answer-table td:before{content:attr(data-label);display:block;color:var(--red);font-weight:bold;margin-bottom:8px}.answer-table select{width:100%;max-width:100%;font-size:20px;min-height:50px}.answer-table th{text-align:left}.answer-label+select{width:100%;min-height:50px}main{padding-bottom:36px}.paper{min-width:0}.panel-list{display:grid;grid-template-columns:1fr}.blank-row select{min-height:48px}.hero .panel{max-height:440px} @media(max-width:400px){.answer-table select{font-size:17px}}

window.LESSON_WORDS = {
  "身材": {
    "meaning": "身体的高矮、胖瘦等整体样子。",
