  },
  "会计师": {
    "meaning": "从事会计专业工作的人。",
    "en": "an accountant",
    "paragraph": 4,
    "example": "可是，爸爸是会计师，他希望我将来也朝这方面发展。"
  },
  "符合": {
    "meaning": "与要求、情况或想法相合。",
    "en": "match or meet a requirement, situation or idea",
    "paragraph": 4,
    "example": "尽管我的梦想不符合爸爸的期望，但我还是想按照自己的兴趣来做选择。"
  },
  "期望": {
    "meaning": "希望达到某种结果。",
    "en": "an expectation or hope for a particular result",
    "paragraph": 4,
    "example": "尽管我的梦想不符合爸爸的期望，但我还是想按照自己的兴趣来做选择。"
  },
  "尽管": {
    "meaning": "表示先承认一种情况，后面再说明另一种结果或做法。",
    "en": "although; acknowledges one situation before stating a different outcome or response",
    "paragraph": 4,
